shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-elevated: #ece6d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.14);
    --navy-bg: #0f1d2b;
    --navy-card: #16283b;
    --navy-line: #28415a;
    --gold: #d99b52;
    --teal: #2a6f78;
    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif: 'Lora', 'Noto Serif SC', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-family: var(--font-serif);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Strict Language Switching Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    background-color: var(--paper);
    color: var(--body);
    overflow-x: hidden;
    line-height: 1.78;
  }

  /* Reading Progress Bar */
  .progress-rail {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 3px;
    background: rgba(20, 20, 19, 0.08);
    z-index: 1001;
  }
  .progress-fill {
    height: 100%;
    width: 0%;
    background: var(--accent);
    transition: width 0.12s ease-out;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.95);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line-strong);
    padding: 0.7rem 1.5rem;
  }
  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }
  .wsj-brand {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    text-decoration: none;
    color: var(--ink);
  }
  .wsj-logo {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.15rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }
  .wsj-sub {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--accent);
    letter-spacing: 0.08em;
    text-transform: uppercase;
    font-weight: 600;
    border-left: 1px solid var(--line-strong);
    padding-left: 0.75rem;
  }
  .masthead-controls {
    display: flex;
    align-items: center;
    gap: 1rem;
  }
  .edition-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: var(--muted);
    letter-spacing: 0.05em;
  }
  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
  }
  .lang-btn {
    appearance: none;
    border: none;
    background: transparent;
    padding: 0.32rem 0.7rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.18s ease;
  }
  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .page-shell {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.5rem 1.5rem 5rem;
  }

  /* Hero Header */
  .article-hero {
    border-bottom: 2px solid var(--ink);
    padding-bottom: 2.25rem;
    margin-bottom: 2.75rem;
  }
  .kicker-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.75rem;
    margin-bottom: 1.1rem;
  }
  .kicker-badge {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 700;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--paper);
    background: var(--accent);
    padding: 0.22rem 0.6rem;
  }
  .kicker-meta {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  .hero-title {
    font-family: var(--font-display);
    font-weight: 800;
    color: var(--ink);
    font-size: clamp(2.1rem, 4.3vw, 3.55rem);
    line-height: 1.16;
    letter-spacing: -0.015em;
    margin-bottom: 1.25rem;
    max-width: 24ch;
  }
  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.26;
    letter-spacing: 0.01em;
    max-width: 26ch;
  }

  .hero-dek {
    font-family: var(--font-serif);
    font-size: clamp(1.08rem, 1.5vw, 1.32rem);
    color: var(--muted);
    line-height: 1.65;
    max-width: 78ch;
    margin-bottom: 1.65rem;
  }

  .byline-strip {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.1rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
  }
  .byline-authors strong {
    color: var(--ink);
    font-weight: 600;
  }
  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.78rem;
  }

  /* Executive Context Dossier Banner (ctx1) */
  .context-dossier {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--accent);
    padding: 1.4rem 1.65rem;
    margin-bottom: 3rem;
    position: relative;
  }
  .dossier-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.65rem;
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--accent);
  }
  .dossier-body {
    font-family: var(--font-sans);
    font-size: 0.94rem;
    line-height: 1.72;
    color: var(--body);
  }

  /* Asymmetric Editorial Grid */
  .editorial-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.65fr) minmax(290px, 1fr);
    gap: 3rem;
    align-items: start;
    margin-bottom: 3.25rem;
  }

  .narrative-col {
    min-width: 0;
  }
  .sidebar-col {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
  }

  /* Section Dividers */
  .section-marker {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    margin: 2.4rem 0 1.35rem;
    padding-top: 1.5rem;
    border-top: 1px solid var(--line-strong);
  }
  .section-marker:first-child {
    margin-top: 0;
    padding-top: 0;
    border-top: none;
  }
  .marker-num {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    color: var(--paper);
    background: var(--ink);
    padding: 0.18rem 0.5rem;
    letter-spacing: 0.06em;
  }
  .marker-title {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--ink);
  }

  /* Prose Paragraphs */
  .prose-p {
    font-family: var(--font-serif);
    font-size: 1.125rem;
    line-height: 1.88;
    color: var(--body);
    margin-bottom: 1.45rem;
  }
  :host([lang="en"]) .prose-p {
    line-height: 1.8;
  }

  /* Lead Paragraph Scale + Border-left (No Chinese drop-cap) */
  .prose-lead {
    font-size: 1.24rem;
    line-height: 1.82;
    color: var(--ink);
    font-weight: 600;
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.65rem;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.18) 0%, rgba(184, 93, 25, 0.26) 100%);
    color: var(--ink);
    padding: 0.06em 0.28em;
    border-bottom: 1.5px solid var(--accent);
    font-weight: 600;
    border-radius: 2px;
  }

  /* Derived Metric Cards */
  .metric-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 1.35rem 1.4rem;
  }
  .metric-card.accent-top {
    border-top-color: var(--accent);
  }
  .metric-eyebrow {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.35rem;
  }
  .metric-val {
    font-family: var(--font-display);
    font-size: 2.35rem;
    font-weight: 800;
    color: var(--accent);
    line-height: 1.1;
    margin-bottom: 0.45rem;
  }
  .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--ink);
    line-height: 1.45;
    margin-bottom: 0.35rem;
  }
  .metric-note {
    font-family: var(--font-mono);
    font-size: 0.73rem;
    color: var(--muted);
  }

  /* Valuation Jump Graphic Box */
  . graphic-panel {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.4rem;
  }
  .graphic-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
    margin-bottom: 0.3rem;
  }
  .graphic-title {
    font-family: var(--font-display);
    font-size: 1.18rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.35rem;
  }
  .graphic-desc {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
    line-height: 1.5;
    margin-bottom: 1rem;
  }
  .graphic-foot {
    font-family: var(--font-mono);
    font-size: 0.71rem;
    color: var(--muted);
    border-top: 1px solid var(--line);
    padding-top: 0.65rem;
    margin-top: 0.75rem;
  }

  /* Navy Technical Architecture Feature Band */
  .architecture-band {
    background: var(--navy-bg);
    color: #f4f1ea;
    border: 1px solid var(--navy-line);
    padding: 2.2rem 2rem;
    margin: 2.75rem 0;
  }
  .arch-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    border-bottom: 1px solid var(--navy-line);
    padding-bottom: 1.15rem;
    margin-bottom: 1.5rem;
  }
  .arch-kicker {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--gold);
    letter-spacing: 0.1em;
    text-transform: uppercase;
    margin-bottom: 0.35rem;
  }
  .arch-title {
    font-family: var(--font-display);
    font-size: 1.55rem;
    font-weight: 700;
    color: #ffffff;
  }
  .arch-sub {
    font-family: var(--font-sans);
    font-size: 0.86rem;
    color: #b7c4d1;
    max-width: 56ch;
  }
  .arch-pills {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    margin-top: 1.35rem;
  }
  .arch-pill {
    background: var(--navy-card);
    border: 1px solid var(--navy-line);
    padding: 1rem 1.1rem;
  }
  .arch-pill-tag {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--gold);
    text-transform: uppercase;
    letter-spacing: 0.07em;
    margin-bottom: 0.3rem;
  }
  .arch-pill-head {
    font-family: var(--font-sans);
    font-size: 0.94rem;
    font-weight: 700;
    color: #fff;
    margin-bottom: 0.3rem;
  }
  .arch-pill-text {
    font-family: var(--font-sans);
    font-size: 0.81rem;
    color: #c2cedb;
    line-height: 1.55;
  }

  /* Founders & Entity Dossier Table */
  .entity-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.35rem 1.45rem;
  }
  .entity-row {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 0.75rem;
    padding: 0.58rem 0;
    border-bottom: 1px dashed var(--line-strong);
    font-family: var(--font-sans);
    font-size: 0.84rem;
  }
  .entity-row:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }
  .entity-key {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    flex-shrink: 0;
  }
  .entity-val {
    color: var(--ink);
    font-weight: 600;
    text-align: right;
  }

  /* Footer */
  .wsj-footer {
    margin-top: 4rem;
    padding-top: 1.75rem;
    border-top: 2px solid var(--ink);
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 860px) {
    .editorial-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .arch-pills {
      grid-template-columns: 1fr;
    }
    .page-shell {
      padding: 1.5rem 1.1rem 3.5rem;
    }
    .architecture-band {
      padding: 1.45rem 1.15rem;
    }
    .masthead {
      padding: 0.65rem 1rem;
    }
    .edition-tag {
      display: none;
    }
  }
